  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vyhlídka na Volos a Pagasetický záliv', 'Hned v prvních serpentinách nad Portarií se otevře výhled na celý Volos a modrý Pagasetický záliv. Ideální první zastávka na kontrolu stroje a fotku, než začne pravé pélionské klikatění mezi platany.', 39.3850, 22.9750, 'https://commons.wikimedia.org/wiki/Special:FilePath/Volos%20view%20from%20Pelion%20(cropped).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Volos%20view%20from%20Pelion%20(cropped).JPG"}'::text[], 0),
    (v_route, 'Makrinitsa', 'Kamenná vesnice přilepená na svahu, přezdívaná balkon Pelionu. Motorku nechte na parkovišti pod vesnicí a projděte se po dlážděném náměstíčku s obřími platany, kašnou a výhledem, který patří k nejfotografovanějším v Thesálii.', 39.3985, 22.9855, 'https://commons.wikimedia.org/wiki/Special:FilePath/Makrinitsa%20village%20in%20Volos%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Makrinitsa%20village%20in%20Volos%20Greece.jpg"}'::text[], 1),
    (v_route, 'Tsagarada – platan na Agia Paraskevi', 'Rozlehlá vesnice na zeleném východním svahu Pelionu. Na náměstí Agia Paraskevi roste tisíciletý platan s korunou přes celé náměstí — přirozené místo na kávu ve stínu po sérii zatáček od hřebene.', 39.3949, 23.1926, 'https://commons.wikimedia.org/wiki/Special:FilePath/Platanus%20Tsangarada%20hc.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Platanus%20Tsangarada%20hc.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tsagkarada%206%20-%20Agia%20Paraskevi.JPG"}'::text[], 2),
    (v_route, 'Pláž Mylopotamos', 'Dvojitá oblázková pláž pod skalním obloukem, jedna z nejkrásnějších v Egejském moři. Sjezd z hlavní silnice je strmý a úzký, ale odměnou je koupání v průzračné vodě přímo pod útesy Tsagarady.', 39.3270, 23.2310, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20Mylopotamos.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20Mylopotamos.jpg"}'::text[], 3),
    (v_route, 'Milies – Pélionská železnice', 'Konečná stanice úzkorozchodné dráhy, kterou koncem 19. století stavěl otec malíře Giorgia de Chirica. V sezóně sem od Volosu supí historický vláček po kamenných viaduktech — nádražíčko s výtopnou je milé místo na protažení nohou.', 39.3280, 23.1480, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pilionbahn%20in%20milies.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pilionbahn%20in%20milies.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pelion%20train.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Mezen (Volos)', 'Volos je hlavní město tsipouradik a Mezen patří k nejlépe hodnoceným — k rundě anýzového tsipoura dostanete pokaždé jiný talířek mořských dobrot. Perfektní tečka za okruhem, motorku už ale nechte zaparkovanou u hotelu.', 39.3610, 22.9440, 'https://commons.wikimedia.org/wiki/Special:FilePath/Volos-bynight.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Volos-bynight.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Delfy – Apollónova věštírna', 'Nejslavnější věštírna starověku na terasách pod skalami Parnassu, památka UNESCO. Kruhový tholos Athény Pronaie je nejfotogeničtější stavbou areálu a výhled do údolí s mořem oliv stojí za časný příjezd, než dorazí autobusy.', 38.4824, 22.5010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Delphi%20tholos%20cazzul.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Delphi%20tholos%20cazzul.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Apollo%20at%20Delphi%202015.jpg"}'::text[], 0),
    (v_route, 'Arachova', 'Horské městečko nalepené na serpentinách nad roklí, v zimě nejrušnější lyžařské středisko Řecka. Kamenné uličky, hodinová věž na skále a krámky s medem, sýrem formaela a vlněnými dekami — v létě příjemně prázdno.', 38.4790, 22.5860, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arachova.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arachova.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Arachova,%20Viotia,%20Greece%20-%20View%20on%20city.jpg"}'::text[], 1),
    (v_route, 'Parnassos – horský přejezd', 'Silnice k lyžařským střediskům Parnassu šplhá přes 1 600 metrů vysoká sedla holou vápencovou krajinou. Mimo zimu je téměř prázdná — dlouhé oblouky, výhledy na půl středního Řecka a chladný horský vzduch i uprostřed léta.', 38.5325, 22.6220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Parnassos2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Parnassos2.jpg"}'::text[], 2),
    (v_route, 'Klášter Osios Loukas', 'Byzantský klášter z 10. století na tichém svahu hory Helikon, památka UNESCO. Katholikon ukrývá nejzachovalejší soubor zlatých mozaik makedonské renesance v Řecku; do areálu se vstupuje v dlouhých kalhotách.', 38.3966, 22.7469, 'https://commons.wikimedia.org/wiki/Special:FilePath/Osiosloukas.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Osiosloukas.JPG"}'::text[], 3),
    (v_route, 'Galaxidi', 'Bývalé město kapitánů na Korintském zálivu s kamennými rejdařskými domy kolem dvou přístavních zátok. Dnes je to jedno z nejpoklidnějších míst na pobřeží — nábřeží lemují kavárny a rybí taverny s výhledem na kotvící plachetnice.', 38.3782, 22.3907, 'https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20harbour.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20harbour.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20Paralia%20at%20Dusk.jpg"}'::text[], 4),
    (v_route, 'Restaurace: O Tassos (Galaxidi)', 'Proslulá rodinná taverna přímo na nábřeží Galaxidi, kam se jezdí na čerstvé ryby, grilované chobotnice a domácí předkrmy. U stolu nad vodou se západem slunce nad zálivem se okruh uzavírá přesně tak, jak má.', 38.3790, 22.3900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20Paralia%20at%20Dusk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20Paralia%20at%20Dusk.jpg"}'::text[], 5);
