  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kardamyli', 'Kamenné městečko mezi mořem a srázy Taygetu, kde prožil většinu života cestovatel Patrick Leigh Fermor. Stará opevněná čtvrť s věžemi rodu Mourtzinos je ochutnávkou maniotské architektury hned na začátku trasy.', 36.8880, 22.2330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kardamili%20main%20street%20in%20town.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kardamili%20main%20street%20in%20town.jpg"}'::text[], 0),
    (v_route, 'Limeni', 'Bývalý přístav Areopole — hrst kamenných domů kolem zátoky s neuvěřitelně průzračnou tyrkysovou vodou, ve které se prohánějí mořské želvy. Jedno z nejfotogeničtějších míst celé Mani, ideální na polední koupel.', 36.6902, 22.3819, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limeni%20Mani.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limeni%20Mani.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Takis (Limeni)', 'Legendární rybí taverna se stoly na molu pár centimetrů nad hladinou. Čerstvé ryby dle denního úlovku, grilovaná chobotnice a výhled na kamenné věže Limeni — rezervace v sezóně nutná, jinak přijeďte mimo poledne.', 36.6899, 22.3826, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limeni.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limeni.jpg"}'::text[], 2),
    (v_route, 'Jeskyně Diros', 'Zatopený jeskynní systém Vlychada, kterým se plujete na loďce mezi lesy krápníků — jedna z nejpůsobivějších jeskynních plaveb v Evropě. Počítejte s hodinou navíc a chladem uvnitř, u vody je i malá pláž na osvěžení.', 36.6386, 22.3810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Diros%20Cave.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Diros%20Cave.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Diros-cave-greece%2016269357444%20o.jpg"}'::text[], 3),
    (v_route, 'Vathia', 'Nejslavnější věžová vesnice Mani na hřebeni nad mořem — kamenné obranné věže z dob krevní msty dnes zpola opuštěné trčí proti obloze jako středověký Manhattan. Nejlepší světlo na fotky je pozdě odpoledne.', 36.4744, 22.4650, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vathia%20Mani%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vathia%20Mani%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vathia%20Mani%20Greece%202.jpg"}'::text[], 4),
    (v_route, 'Mys Tenaro – maják', 'Nejjižnější bod pevninského Řecka, kde staří Řekové umísťovali vchod do Hádovy říše. Od parkoviště u kaple je to půlhodina pěšky kamenitou stezkou k osamělému majáku — vezměte vodu a pevné boty, výhled na tři moře za to stojí.', 36.3862, 22.4829, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Tainaron%20lighthouse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Tainaron%20lighthouse.jpg"}'::text[], 5);
  insert into public.routes
