  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Dimitsana', 'Amfiteátr kamenných domů nad soutěskou Lousios, za řecké revoluce zásobárna střelného prachu povstalců. Úzká hlavní ulice s kavárnami a pekárnami je stvořená pro první zastávku; výhled z horního konce vesnice bere dech.', 37.5946, 22.0431, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stone%20mansion%20in%20Dimitsana,%20Greece%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stone%20mansion%20in%20Dimitsana,%20Greece%20-%20panoramio.jpg"}'::text[], 0),
    (v_route, 'Muzeum vodní síly (Dimitsana)', 'Skanzen pod Dimitsanou u pramenů, kde voda kdysi poháněla mlýny, valchy, koželužnu i prachárnu. Vše je zrestaurované a funkční — půlhodinová zastávka, po které pochopíte, proč bylo tohle údolí průmyslovým centrem Peloponésu.', 37.5880, 22.0450, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hydro%20power%20museum%20at%20Dimitsana.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hydro%20power%20museum%20at%20Dimitsana.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gunpowder%20watermill%20at%20Dimitsana%20hydropower%20museum.JPG"}'::text[], 1),
    (v_route, 'Soutěska Lousios', 'Hluboký kaňon řeky, kterou se podle mýtu koupal malý Zeus. Do skalních stěn jsou vlepené kláštery Prodromou a Filosofou; z vyhlídek u silnice mezi Dimitsanou a Stemnitsou je vidí i ten, kdo nechce šlapat pěšky.', 37.5600, 22.0500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lousios%20river.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lousios%20river.jpg"}'::text[], 2),
    (v_route, 'Stemnitsa', 'Vesnice zlatníků a stříbrotepců ukrytá v jedlích pod horou Klinitsa, s kamennou zvonicí na náměstíčku a proslulou zlatnickou školou. V kavárnách pod platany si dejte místní sladkost skaltsounia a kávu z briki.', 37.5535, 22.0463, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bell%20tower%20in%20Stemnitsa,%20Greece%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bell%20tower%20in%20Stemnitsa,%20Greece%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Karytaina', 'Vesnice pod mohutnou franckou pevností ze 13. století, přezdívaná řecké Toledo. Hrad hlídá soutok údolí a starý kamenný most pod ním kdysi zdobil pětitisícovou drachmovou bankovku — krátká pěší odbočka nahoru nabídne výhled na celou Arkádii.', 37.4886, 22.0402, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karytainaview.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karytainaview.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Dion – antické město', 'Posvátné město Makedonců na úpatí Olympu, kde Alexandr Veliký obětoval bohům před tažením do Asie. Mezi topoly a potoky tu leží svatyně Dia i Isidy, lázně a divadlo — rovinatý areál se prochází příjemně i v motorkářských botách.', 40.1717, 22.4913, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dion%20archaeological%20site%20102.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dion%20archaeological%20site%20102.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20santuary%20of%20Zeus%20Olympios,%20Ancient%20Dion%20(6933396342).jpg"}'::text[], 0),
    (v_route, 'Litochoro', 'Městečko přímo pod stěnami Olympu, základna všech výprav na horu bohů. Z náměstí s kašnou je přímý výhled do ústí soutěsky Enipeas na štít Mytikas — kávu si dejte na terase a nechte kolemjdoucí závidět motorku.', 40.1044, 22.5006, 'https://commons.wikimedia.org/wiki/Special:FilePath/Olympus%20Litochoro.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Olympus%20Litochoro.JPG"}'::text[], 1),
    (v_route, 'Restaurace: Gastrodromio En Olympo (Litochoro)', 'Nejproslulejší restaurace pod Olympem — moderní řecká kuchyně z horských surovin, jehněčí, lesní houby a vinný lístek, jaký byste v podhůří nečekali. Po serpentinách z Prionie ideální místo na pořádný oběd.', 40.1049, 22.5000, 'https://commons.wikimedia.org/wiki/Special:FilePath/Litochoro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Litochoro.jpg"}'::text[], 2),
    (v_route, 'Soutěska Enipeas a Prionia', 'Osmnáct kilometrů serpentin z Litochora nad soutěskou řeky Enipeas až na Prionii, kde asfalt končí pod skalními věžemi Olympu. Jedna z nejpůsobivějších horských silnic Řecka — jeďte brzy ráno, vyhnete se koloně aut turistů mířících na trailhead.', 40.1073, 22.4143, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Olympus,%20Greece%20(Unsplash).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Olympus,%20Greece%20(Unsplash).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/At%20Enipeas%20gorge%20(2).jpg"}'::text[], 3),
    (v_route, 'Palaios Panteleimonas', 'Kamenná vesnice na svahu Dolního Olympu, citlivě zrestaurovaná do poslední tašky. Z platany zastíněného náměstí s tavernami se otevírá výhled přes Egejské moře až k hradu Platamon hluboko dole — příjezdová silnička je úzká, ale krásná.', 40.0100, 22.5850, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palaios%20Panteleimonas%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palaios%20Panteleimonas%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Palaios%20Panteleimonas.jpg"}'::text[], 4),
    (v_route, 'Hrad Platamon', 'Křižácká pevnost z 13. století na skále mezi dálnicí a mořem, strážící vstup do Tempského údolí. Z hradeb je panoráma od Olympu po Chalkidiki; pod hradem lákají pláže Platamonas na rychlé osvěžení před návratem.', 39.9997, 22.6042, 'https://commons.wikimedia.org/wiki/Special:FilePath/Platamon%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Platamon%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Platamon%20castro.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Preveza', 'Přístavní městečko u ústí Ambrakijského zálivu s benátskou pevností Pantokrator a stinnými uličkami plnými kaváren. Na start trasy se sem pohodlně dostanete podmořským tunelem z Aktia — jediným svého druhu v Řecku.', 38.9560, 20.7500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pantokratoras%20Castle,%20Preveza%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pantokratoras%20Castle,%20Preveza%202.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Amvrosios (Preveza)', 'Kultovní taverna v rybářské uličce u přístavu, proslavená grilovanými sardinkami a domácím vínem za pár eur. Jednoduché stoly, žádné menu pro turisty — přesně tak chutná skutečný Epirus, ideální časný oběd před vyjížďkou na sever.', 38.9565, 20.7515, 'https://commons.wikimedia.org/wiki/Special:FilePath/Promenade%20of%20Preveza,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Promenade%20of%20Preveza,%20Greece.jpg"}'::text[], 1),
    (v_route, 'Nekromanteion – věštírna mrtvých', 'Na kopci nad soutokem Acherontu stála jediná známá věštírna mrtvých antického světa — poutníci tu v podzemní kryptě rozmlouvali s dušemi zemřelých. Mystické místo s výhledem na deltu bájné řeky, vstup zabere půl hodiny.', 39.2358, 20.5342, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nekromanteion%20of%20Acheron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nekromanteion%20of%20Acheron.jpg"}'::text[], 2),
    (v_route, 'Prameny Acherontu (Glyki)', 'U vesnice Glyki vyvěrá řeka podsvětí ze soutěsky ledovými prameny — v létě se tu turisté brodí křišťálovou vodou mezi platany a skalami. Osvěžující zastávka s tavernami u břehu; voda má i v srpnu kolem deseti stupňů.', 39.3216, 20.6094, 'https://commons.wikimedia.org/wiki/Special:FilePath/Acheron%20Springs,%20Preveza%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Acheron%20Springs,%20Preveza%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Acheron%20river%202.jpg"}'::text[], 3),
    (v_route, 'Parga', 'Amfiteátr pestrobarevných domů kolem zátoky s ostrůvkem Panagia a benátským hradem na ostrohu. Nejmalebnější městečko epirského pobřeží — vyjeďte k hradu, odkud je celá scenérie s pláží Valtos jako na dlani.', 39.2850, 20.4010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Parga,%20Grekland.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Parga,%20Grekland.JPG"}'::text[], 4),
    (v_route, 'Sivota', 'Rybářský přístav proti souostroví drobných zelených ostrůvků, přezdívaný Karibik Jónského moře. Kolem zátoky Bella Vraka svítí bílý písek a tyrkys; večer na nábřeží u kotvících jachet chutná ouzo nejlíp z celé trasy.', 39.4079, 20.2447, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Harbour%20of%20Syvota.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Harbour%20of%20Syvota.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Nikiti – stará čtvrť', 'Vstupní brána Sithonie se starou čtvrtí kamenných domů a kostelíků na kopci nad letoviskem. Ideální místo na ranní kávu a tankování před okruhem — odtud už silnice vede jen podél moře.', 40.2180, 23.6700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nikiti%20old%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nikiti%20old%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nikiti,%20Halkidiki,%20Greece.jpg"}'::text[], 0),
    (v_route, 'Neos Marmaras', 'Živé přístavní městečko v borovicových svazích se dvěma zátokami a marínou plnou jachet. Na nábřeží je řada kaváren s výhledem na ostrůvek Kelyfos; nad městem se zvedá vinařství Porto Carras, největší vinice Řecka.', 40.0947, 23.7826, 'https://commons.wikimedia.org/wiki/Special:FilePath/NeosMarmarasMarina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NeosMarmarasMarina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Neos%20Marmaras,%20Chalkidiki,%20Greece.jpg"}'::text[], 1),
    (v_route, 'Parthenonas', 'Jediná zachovaná horská vesnice Sithonie ve svahu hory Itamos, kdysi vylidněná a dnes citlivě opravená. Krátká serpentinová odbočka z Neos Marmaras nahoru je zábavná sama o sobě a výhled na záliv Toroneos stojí za každou zatáčku.', 40.1030, 23.8180, 'https://commons.wikimedia.org/wiki/Special:FilePath/PARTHENONAS.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/PARTHENONAS.jpg"}'::text[], 2),
    (v_route, 'Restaurace: O Platanos (Parthenonas)', 'Taverna pod platanem na návsi Parthenonas s poctivou domácí kuchyní — jehněčí z gril, sezónní zelenina a výhled přes střechy až k moři. Po ránu klid, večer romantika; oblíbené místo, v sezóně raději rezervujte.', 40.1032, 23.8175, 'https://commons.wikimedia.org/wiki/Special:FilePath/PARTHENONAS%20BY%20NIGHT.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/PARTHENONAS%20BY%20NIGHT.jpg"}'::text[], 3),
    (v_route, 'Porto Koufo', 'Největší přírodní přístav Řecka — téměř uzavřený fjord mezi vysokými útesy na jižním cípu poloostrova, známý už Thúkydidovi. V rybářských tavernách u mola mají denně čerstvé ryby; útesy u vjezdu nabízejí divoké výhledy na otevřené moře.', 39.9620, 23.9200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Porto%20Koufo,%20Sithonia,%20Chalkidiki,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Porto%20Koufo,%20Sithonia,%20Chalkidiki,%20Greece.jpg"}'::text[], 4),
    (v_route, 'Sarti', 'Letovisko s dlouhou písečnou pláží na východním pobřeží, odkud je nejblíž k mystické siluetě hory Athos přes záliv. Východní strana Sithonie je divočejší a silnice tu nabízí nejhezčí sled zatáček s mořem pod kolem.', 40.0928, 24.0107, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sarti,%20church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sarti,%20church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sarti%20630%2072,%20Greece%20-%20panoramio%20(5).jpg"}'::text[], 5),
    (v_route, 'Vourvourou a pláž Karydi', 'Mělká laguna s rozesetými ostrůvky Diaporos a slavná pláž Karydi s bílým pískem a hladkými žulovými balvany. Voda tu má barvu, kterou nikdo nefotí věrně — poslední koupání okruhu, pak už jen pohodový dojezd do Nikiti.', 40.1900, 23.8200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karidi%20beach,%20Sithonia,%20Chalkidiki,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karidi%20beach,%20Sithonia,%20Chalkidiki,%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vourvourou%20beach%20sithonia%2001.jpg"}'::text[], 6);
