  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Chania – benátský přístav', 'Nejkrásnější město Kréty s benátským přístavem, egyptským majákem a spletí uliček staré čtvrti Topanas. Startujte brzy ráno, kdy je nábřeží prázdné a světlo na maják nejhezčí — večer se sem vrátíte na promenádu.', 35.5176, 24.0180, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Old%20Venetian%20Harbour%20in%20Chania,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Old%20Venetian%20Harbour%20in%20Chania,%20Greece.jpg"}'::text[], 0),
    (v_route, 'Soutěska Topolia', 'Silnice na Elafonisi se protahuje úzkou soutěskou pod převislými skalami a jednosměrným tunelem vytesaným do útesu — na semaforu si užijte pohled vzhůru. Kousek za tunelem je jeskyně Agia Sofia s kapličkou v krasovém dómu.', 35.4210, 23.6810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Topolia%20Gorge%20-%20Crete,%20Greece%20(2).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Topolia%20Gorge%20-%20Crete,%20Greece%20(2).jpg"}'::text[], 1),
    (v_route, 'Elafonisi', 'Laguna s bílým a růžovým pískem, brodem na ostrůvek a vodou po kolena do půlky zálivu — chráněná rezervace Natura 2000 a jedna z nejslavnějších pláží Středomoří. Serpentiny posledních kilometrů nad Libyjským mořem jsou samy o sobě zážitek.', 35.2716, 23.5416, 'https://commons.wikimedia.org/wiki/Special:FilePath/Elafonisi%20Greece%20Crete%2016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Elafonisi%20Greece%20Crete%2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Elafonisi%20Lagoon%20and%20Beach%20in%20Greece.jpg"}'::text[], 2),
    (v_route, 'Falassarna', 'Pět kilometrů zlatého písku pod svahy mysu Gramvousa s ruinami antického přístavu na severním konci. Západy slunce tu bývají vyhlášené nejhezčími na Krétě — pokud to čas dovolí, zdržte se do večera a do Chanie se vraťte po setmění.', 35.4936, 23.5786, 'https://commons.wikimedia.org/wiki/Special:FilePath/Creta,spiaggia%20di%20Falassarna%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Creta,spiaggia%20di%20Falassarna%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Falassarna%20-%20Kr%C3%A9ta%20-%20panoramio%20(4).jpg"}'::text[], 3),
    (v_route, 'Kissamos', 'Přístavní městečko v hlubokém zálivu mezi poloostrovy Gramvousa a Rodopou, odkud vyplouvají lodě k laguně Balos. Klidnější tvář západní Kréty s archeologickým muzeem a tavernami, kam turisté z resortů nedorazí.', 35.4940, 23.6550, 'https://commons.wikimedia.org/wiki/Special:FilePath/Port%20of%20Kissamos%20in%20Crete,%20Greece%20001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20of%20Kissamos%20in%20Crete,%20Greece%20001.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Tamam (Chania)', 'Vyhlášená restaurace v bývalých tureckých lázních kousek od přístavu — krétská a levantská kuchyně, skvělé vegetariánské meze a domácí víno. Po celodenním okruhu ideální večeře; přijďte dřív, stoly v uličce se plní rychle.', 35.5170, 24.0150, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Old%20Venetian%20Harbour%20in%20Chania,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Old%20Venetian%20Harbour%20in%20Chania,%20Greece.jpg"}'::text[], 5);
