  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Nafplio – pevnost Palamidi', 'První hlavní město novodobého Řecka pod benátskou pevností Palamidi a s vodním hrádkem Bourtzi v zálivu. Stará čtvrť s neoklasicistními domy, bugenvilejemi a kavárnami na Syntagmatu je nejhezčí městská kulisa Peloponésu.', 37.5663, 22.8014, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palamidi%20fortress%20(Nafplio,%20Greece).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palamidi%20fortress%20(Nafplio,%20Greece).jpg"}'::text[], 0),
    (v_route, 'Mykény – Lví brána', 'Citadela Agamemnonova rodu, srdce mykénské civilizace a památka UNESCO. Lví bránou z 13. století před naším letopočtem procházíte do hradu mezi kyklopskými zdmi; nevynechejte úlovou hrobku zvanou Átreova pokladnice u parkoviště.', 37.7308, 22.7566, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lions-Gate-Mycenae.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lions-Gate-Mycenae.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Lion%20Gate,%20Mycenae.jpg"}'::text[], 1),
    (v_route, 'Starověký Korint', 'Rozvaliny antické metropole pod skalou Akrokorintu s archaickým Apollónovým chrámem, jehož monolitické sloupy stojí už dvacet šest století. Odtud kázal apoštol Pavel Korinťanům; na Akrokorint vede krátká, ale strmá asfaltka s výhledem na oba zálivy.', 37.9059, 22.8797, 'https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Apollo%20Ancient%20Corinth.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Apollo%20Ancient%20Corinth.jpg"}'::text[], 2),
    (v_route, 'Korintský průplav', 'Šest kilometrů dlouhý zářez v šíji mezi Egejským a Jónským mořem, s kolmými stěnami vysokými přes sedmdesát metrů. Z mostu staré národní silnice je závratný pohled na lodě hluboko dole — odvážlivci tu skáčou bungee.', 37.9333, 22.9833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Corinth%20Canal%20(corinth-canal).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Corinth%20Canal%20(corinth-canal).jpg"}'::text[], 3),
    (v_route, 'Divadlo v Epidauru', 'Nejdokonalejší antické divadlo světa se čtrnácti tisíci sedadly a akustikou, díky níž je škrtnutí sirkou na jevišti slyšet i v poslední řadě. Cesta z Epidauru do Nafplia borovicovými kopci je motorkářský bonus na závěr.', 37.5961, 23.0791, 'https://commons.wikimedia.org/wiki/Special:FilePath/Theatre%20of%20Epidaurus%20OLC.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Theatre%20of%20Epidaurus%20OLC.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Theatre%20of%20Epidaurus,%20202508.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Ta Fanaria (Nafplio)', 'Stará dobrá taverna v uličce pod Palamidi, kde se pod bugenvileou podávají klasiky jako moussaka, jehněčí kleftiko a domácí retsina. Po dni mezi památkami zasloužená večeře pár kroků od náměstí Syntagma.', 37.5678, 22.8087, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nafplio%20(Nauplia),%20Argolis%20(Argolida),%20Greece.%20View%20from%20the%20Fort.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nafplio%20(Nauplia),%20Argolis%20(Argolida),%20Greece.%20View%20from%20the%20Fort.jpg"}'::text[], 5);
