  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Jezero Vouliagmeni', 'Termální jezero v propadlé krasové jeskyni pár metrů od moře — voda má celoročně kolem 24 stupňů a mírně léčivé složení. Elegantní zastávka na kávu nebo ranní koupel, než se pobřežní silnice rozběhne k jihu.', 37.8064, 23.7862, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limni%20Vouliagmenis%20kalokairi.JPEG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limni%20Vouliagmenis%20kalokairi.JPEG"}'::text[], 0),
    (v_route, 'Chrám Poseidona na mysu Sounion', 'Dórský chrám boha moří ze 5. století před naším letopočtem na útesu šedesát metrů nad Egejským mořem. Podle mýtu se odtud vrhl do vln král Aigeus; do jednoho sloupu vyryl své jméno lord Byron. Při západu slunce nezapomenutelné.', 37.6503, 24.0203, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Sounion%20and%20temple%20of%20Poseidon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Sounion%20and%20temple%20of%20Poseidon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Poseidon%202%20Cape%20Sounion%20Greece.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Syrtaki (Sounion)', 'Rybí taverna na svahu pod chrámem s terasou nad zálivem — grilované ryby, kalamáry a výhled přímo na Poseidonův chrám na protějším ostrohu. Ideální pozdní oběd před návratem po pobřežce, při západu slunce romantika první třídy.', 37.6560, 24.0250, 'https://commons.wikimedia.org/wiki/Special:FilePath/Capo%20Sounion%20panorama.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Capo%20Sounion%20panorama.JPG"}'::text[], 2),
    (v_route, 'Lavrio – město stříbrných dolů', 'Přístavní město, jehož stříbrné doly financovaly athénské loďstvo i stavbu Parthenónu. Hornickou minulost připomínají štoly, haldy a mineralogické muzeum s ukázkami vzácných minerálů, které svět zná právě odsud; na náměstí u přístavu je příjemná kavárenská pauza.', 37.7146, 24.0566, 'https://commons.wikimedia.org/wiki/Special:FilePath/Agardite%20Lavrio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Agardite%20Lavrio.jpg"}'::text[], 3),
    (v_route, 'Vravrona – svatyně Artemidy', 'Tiché vykopávky svatyně bohyně Artemis v mokřadech u moře, kam athénské rodiny posílaly dcery sloužit jako „medvědice". Obnovená kolonáda stoy, kamenný most z klasické éry a muzeum s dojemnými soškami dětí — klidná tečka před návratem do Athén.', 37.9262, 23.9945, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brauron%20-%20Votive%20Relief3.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brauron%20-%20Votive%20Relief3.jpg"}'::text[], 4);
