-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — ŘECKO (10 tras, sort_order 4010–4100)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Pelion – poloostrov kentaurů
  delete from public.routes where name = 'Pelion – poloostrov kentaurů' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Pelion – poloostrov kentaurů', 'Okruh po hoře Pelion, kde podle mýtů žili kentauři, je jednou z nejhezčích motorkářských vyjížděk pevninského Řecka. Z Volosu stoupáte úzkými serpentinami mezi kaštanovými lesy do kamenných vesnic Makrinitsa a Tsagarada a na východním pobřeží se silnice stáčí k tyrkysové pláži Mylopotamos. Zpátky vede cesta přes Milies, konečnou stanici legendární úzkorozchodné železnice. Asfalt je vesměs dobrý, ale silnice jsou úzké, plné slepých zatáček a v sezóně potkáte autobusy — jezděte předvídavě. Nejlépe od května do října; brzy zjara bývá na hřebeni mokro a listí na silnici. Večer si ve Volosu dopřejte tsipouradiko, místní rituál drobných rybích chodů.', 'loop', 135, 240, 'medium',
     '[{"lat": 39.3622, "lng": 22.9420, "label": "Start: Volos"}, {"lat": 39.3985, "lng": 22.9855, "label": "Makrinitsa"}, {"lat": 39.3949, "lng": 23.1926, "label": "Tsagarada"}, {"lat": 39.3270, "lng": 23.2310, "label": "Pláž Mylopotamos"}, {"lat": 39.3280, "lng": 23.1480, "label": "Milies"}, {"lat": 39.3622, "lng": 22.9420, "label": "Cíl: Volos"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=39.3622,22.9420&destination=39.3622,22.9420&travelmode=driving&waypoints=39.3985,22.9855%7C39.3949,23.1926%7C39.3270,23.2310%7C39.3280,23.1480', 'https://commons.wikimedia.org/wiki/Special:FilePath/Makrinitsa%20village%20in%20Volos%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Volos%20view%20from%20Pelion%20(cropped).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Makrinitsa%20village%20in%20Volos%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Platanus%20Tsangarada%20hc.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20Mylopotamos.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pilionbahn%20in%20milies.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Volos-bynight.JPG"}'::text[], '{"Vyhlídka na Volos a Pagasetický záliv","Makrinitsa","Tsagarada – platan na Agia Paraskevi","Pláž Mylopotamos","Milies – Pélionská železnice","Restaurace: Mezen (Volos)"}'::text[], '{"GR"}'::text[], false, 4010, 'approved');

  -- Delfy, Parnassos a Galaxidi
  delete from public.routes where name = 'Delfy, Parnassos a Galaxidi' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Delfy, Parnassos a Galaxidi', 'Okruh kolem hory Parnassos spojuje antický „střed světa" s horskými serpentinami a přímořskou pohodou Korintského zálivu. Z přístavu Itea vystoupáte olivovým hájem k delfské věštírně a do lyžařské Arachovy, odkud pokračuje prázdná horská silnice přes sedla Parnassu k byzantskému klášteru Osios Loukas. Zpáteční cesta padá dlouhými zatáčkami zpět k moři do námořnického městečka Galaxidi. Povrch je převážně výborný, jen na horských úsecích čekejte štěrk v zatáčkách a volně se pasoucí kozy. Ideální období je duben až červen a září až říjen — v létě bývá u Delf výheň a davy. Brzy ráno projedete areál věštírny téměř sami.', 'loop', 150, 240, 'medium',
     '[{"lat": 38.4325, "lng": 22.4243, "label": "Start: Itea"}, {"lat": 38.4824, "lng": 22.5010, "label": "Delfy"}, {"lat": 38.4790, "lng": 22.5860, "label": "Arachova"}, {"lat": 38.5325, "lng": 22.6220, "label": "Parnassos"}, {"lat": 38.3966, "lng": 22.7469, "label": "Osios Loukas"}, {"lat": 38.3782, "lng": 22.3907, "label": "Galaxidi"}, {"lat": 38.4325, "lng": 22.4243, "label": "Cíl: Itea"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=38.4325,22.4243&destination=38.4325,22.4243&travelmode=driving&waypoints=38.4824,22.5010%7C38.4790,22.5860%7C38.5325,22.6220%7C38.3966,22.7469%7C38.3782,22.3907', 'https://commons.wikimedia.org/wiki/Special:FilePath/Delphi%20tholos%20cazzul.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Delphi%20tholos%20cazzul.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Arachova.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parnassos2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Osiosloukas.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20harbour.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Galaxidi%20Paralia%20at%20Dusk.jpg"}'::text[], '{"Delfy – Apollónova věštírna","Arachova","Parnassos – horský přejezd","Klášter Osios Loukas","Galaxidi","Restaurace: O Tassos (Galaxidi)"}'::text[], '{"GR"}'::text[], false, 4020, 'approved');

  -- Mani – věžové domy a mys Tenaro
  delete from public.routes where name = 'Mani – věžové domy a mys Tenaro' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Mani – věžové domy a mys Tenaro', 'Cesta na nejdivočejší poloostrov Peloponésu, kde kamenné věžové domy hlídají vyprahlou krajinu a silnice končí u bájné brány do podsvětí. Z Kalamaty se pobřežní silnice vlní nad tyrkysovými zátokami přes Kardamyli do Limeni a dál na jih k jeskyním Diros a věžím Vathie, až k majáku na mysu Tenaro — nejjižnějším výběžku pevninského Řecka. Zatáčky nad mořem jsou plynulé, ale krajnice bývají štěrkové a v horku přebíhají silnici kozy. Nejlepší jsou květen, červen a září; v červenci a srpnu počítejte s úmorným vedrem a slabým stínem. Benzín natankujte v Areopoli, dál na jih jsou pumpy vzácné.', 'poi', 175, 300, 'medium',
     '[{"lat": 37.0389, "lng": 22.1142, "label": "Start: Kalamata"}, {"lat": 36.8880, "lng": 22.2330, "label": "Kardamyli"}, {"lat": 36.6902, "lng": 22.3819, "label": "Limeni"}, {"lat": 36.6386, "lng": 22.3810, "label": "Jeskyně Diros"}, {"lat": 36.4744, "lng": 22.4650, "label": "Vathia"}, {"lat": 36.4006, "lng": 22.4818, "label": "Mys Tenaro"}, {"lat": 36.7607, "lng": 22.5664, "label": "Cíl: Gythio"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=37.0389,22.1142&destination=36.7607,22.5664&travelmode=driving&waypoints=36.8880,22.2330%7C36.6902,22.3819%7C36.6386,22.3810%7C36.4744,22.4650%7C36.4006,22.4818', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vathia%20Mani%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kardamili%20main%20street%20in%20town.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Limeni%20Mani.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Limeni.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Diros%20Cave.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vathia%20Mani%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Tainaron%20lighthouse.jpg"}'::text[], '{"Kardamyli","Limeni","Restaurace: Takis (Limeni)","Jeskyně Diros","Vathia","Mys Tenaro – maják"}'::text[], '{"GR"}'::text[], false, 4030, 'approved');

  -- Arkádie – Dimitsana a soutěska Lousios
  delete from public.routes where name = 'Arkádie – Dimitsana a soutěska Lousios' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Arkádie – Dimitsana a soutěska Lousios', 'Horské srdce Peloponésu je přesně ta Arkádie, kterou opěvovali básníci: hluboká údolí, jedlové lesy a kamenné vesnice na srázech. Okruh z Tripoli projíždí serpentinami soutěsky Lousios přes Dimitsanu a Stemnitsu ke zřícenině franckého hradu v Karytaině. Silnice jsou úzké, samá zatáčka a téměř bez provozu — technicky jedna z nejzábavnějších tras Peloponésu. Na jaře kvetou stráně a řeka Lousios burácí, na podzim hrají lesy barvami; v zimě může na hřebenech ležet sníh. Pozor na štěrk po zimě a na stáda ovcí za slepými zatáčkami. Palivo doplňte v Tripoli nebo ve Vytině.', 'loop', 160, 270, 'medium',
     '[{"lat": 37.5089, "lng": 22.3794, "label": "Start: Tripoli"}, {"lat": 37.5946, "lng": 22.0431, "label": "Dimitsana"}, {"lat": 37.5535, "lng": 22.0463, "label": "Stemnitsa"}, {"lat": 37.4886, "lng": 22.0402, "label": "Karytaina"}, {"lat": 37.4010, "lng": 22.1420, "label": "Megalopoli"}, {"lat": 37.5089, "lng": 22.3794, "label": "Cíl: Tripoli"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=37.5089,22.3794&destination=37.5089,22.3794&travelmode=driving&waypoints=37.5946,22.0431%7C37.5535,22.0463%7C37.4886,22.0402%7C37.4010,22.1420', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stone%20mansion%20in%20Dimitsana,%20Greece%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stone%20mansion%20in%20Dimitsana,%20Greece%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hydro%20power%20museum%20at%20Dimitsana.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lousios%20river.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bell%20tower%20in%20Stemnitsa,%20Greece%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karytainaview.JPG"}'::text[], '{"Dimitsana","Muzeum vodní síly (Dimitsana)","Soutěska Lousios","Stemnitsa","Karytaina"}'::text[], '{"GR"}'::text[], false, 4040, 'approved');

  -- Olymp – hora bohů a hrad Platamon
  delete from public.routes where name = 'Olymp – hora bohů a hrad Platamon' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Olymp – hora bohů a hrad Platamon', 'Okruh kolem nejvyšší hory Řecka spojuje antické Dion, serpentiny do srdce národního parku a středověký hrad nad mořem. Vrcholem je osmnáct kilometrů zatáček z Litochora na Prionii — silnice končí v 1 100 metrech přímo pod skalními štíty Olympu a jinudy než zpátky to nejde, o to víc si ji užijete. Cestou na jih se vyplatí odbočka do kamenné vesnice Palaios Panteleimonas a k hradu Platamon nad pobřežím. Asfalt je slušný, ale v horní části čekejte popadané kamení a v sezóně pomalé kolony k trailheadu. Nejhezčí je červen, kdy na vrcholcích ještě leží sníh, a pak září s křišťálovou viditelností. Ráno bývá hora čistá, odpoledne se štíty zatahují.', 'loop', 150, 240, 'medium',
     '[{"lat": 40.2719, "lng": 22.5025, "label": "Start: Katerini"}, {"lat": 40.1717, "lng": 22.4913, "label": "Dion"}, {"lat": 40.1044, "lng": 22.5006, "label": "Litochoro"}, {"lat": 40.1073, "lng": 22.4143, "label": "Prionia"}, {"lat": 40.0100, "lng": 22.5850, "label": "Palaios Panteleimonas"}, {"lat": 39.9997, "lng": 22.6042, "label": "Hrad Platamon"}, {"lat": 40.2719, "lng": 22.5025, "label": "Cíl: Katerini"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=40.2719,22.5025&destination=40.2719,22.5025&travelmode=driving&waypoints=40.1717,22.4913%7C40.1044,22.5006%7C40.1073,22.4143%7C40.0100,22.5850%7C39.9997,22.6042', 'https://commons.wikimedia.org/wiki/Special:FilePath/Olympus%20Litochoro.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dion%20archaeological%20site%20102.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Olympus%20Litochoro.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Litochoro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Olympus,%20Greece%20(Unsplash).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Palaios%20Panteleimonas%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Platamon%20Castle.jpg"}'::text[], '{"Dion – antické město","Litochoro","Restaurace: Gastrodromio En Olympo (Litochoro)","Soutěska Enipeas a Prionia","Palaios Panteleimonas","Hrad Platamon"}'::text[], '{"GR"}'::text[], false, 4050, 'approved');

  -- Epirus – Parga, Sivota a řeka Acheron
  delete from public.routes where name = 'Epirus – Parga, Sivota a řeka Acheron' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Epirus – Parga, Sivota a řeka Acheron', 'Pobřežní putování Epirem od Preverzy k Sivotě, kde se jónské pobřeží podobá Karibiku a mezi olivami se skrývají místa antických mýtů. Cestou navštívíte věštírnu mrtvých nad soutokem Acherontu, ledové prameny bájné řeky podsvětí v Glyki a benátské městečko Parga s hradem nad zálivem. Silnice se vlní mezi olivovými háji a mořem — technicky nenáročné, zato scenericky velkolepé kilometry. Ideální od května do začátku října; v srpnu je v Parze plno, ale stačí přijet dopoledne. U Acherontu se v létě zchladíte broděním v průzračné vodě, vezměte sandály. Trasa navazuje na trajekt z Itálie do Igoumenitsy, hodí se jako první den řeckého okruhu.', 'poi', 130, 210, 'easy',
     '[{"lat": 38.9560, "lng": 20.7500, "label": "Start: Preveza"}, {"lat": 39.2358, "lng": 20.5342, "label": "Nekromanteion"}, {"lat": 39.3216, "lng": 20.6094, "label": "Glyki – prameny Acherontu"}, {"lat": 39.2850, "lng": 20.4010, "label": "Parga"}, {"lat": 39.4079, "lng": 20.2447, "label": "Cíl: Sivota"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=38.9560,20.7500&destination=39.4079,20.2447&travelmode=driving&waypoints=39.2358,20.5342%7C39.3216,20.6094%7C39.2850,20.4010', 'https://commons.wikimedia.org/wiki/Special:FilePath/Parga,%20Grekland.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pantokratoras%20Castle,%20Preveza%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Promenade%20of%20Preveza,%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nekromanteion%20of%20Acheron.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Acheron%20Springs,%20Preveza%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parga,%20Grekland.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Harbour%20of%20Syvota.JPG"}'::text[], '{"Preveza","Restaurace: Amvrosios (Preveza)","Nekromanteion – věštírna mrtvých","Prameny Acherontu (Glyki)","Parga","Sivota"}'::text[], '{"GR"}'::text[], false, 4060, 'approved');

  -- Chalkidiki – okruh Sithonií
  delete from public.routes where name = 'Chalkidiki – okruh Sithonií' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Chalkidiki – okruh Sithonií', 'Okruh prostředního prstu Chalkidiki je nejhezčí pobřežní vyjížďka severního Řecka: silnice kopíruje břeh mezi piniemi a desítkami tyrkysových zátok a přes záliv se celý den zjevuje silueta posvátné hory Athos. Po cestě střídáte přímořská městečka Neos Marmaras a Sarti s horskou odbočkou do kamenné vesnice Parthenonas a přírodním přístavem Porto Koufo. Asfalt je kvalitní, převýšení mírné a zatáčky plynulé — pohodová trasa i pro méně zkušené. Nejlépe v červnu nebo září, kdy je moře teplé a silnice prázdné; o prázdninách počítejte s provozem u pláží. Plavky mějte po ruce, zastávek na koupání je nepočítaně.', 'loop', 115, 180, 'easy',
     '[{"lat": 40.2180, "lng": 23.6700, "label": "Start: Nikiti"}, {"lat": 40.0947, "lng": 23.7826, "label": "Neos Marmaras"}, {"lat": 40.1030, "lng": 23.8180, "label": "Parthenonas"}, {"lat": 39.9620, "lng": 23.9200, "label": "Porto Koufo"}, {"lat": 40.0928, "lng": 24.0107, "label": "Sarti"}, {"lat": 40.1950, "lng": 23.7960, "label": "Vourvourou"}, {"lat": 40.2180, "lng": 23.6700, "label": "Cíl: Nikiti"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=40.2180,23.6700&destination=40.2180,23.6700&travelmode=driving&waypoints=40.0947,23.7826%7C40.1030,23.8180%7C39.9620,23.9200%7C40.0928,24.0107%7C40.1950,23.7960', 'https://commons.wikimedia.org/wiki/Special:FilePath/Porto%20Koufo,%20Sithonia,%20Chalkidiki,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nikiti%20old%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NeosMarmarasMarina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/PARTHENONAS.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/PARTHENONAS%20BY%20NIGHT.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Porto%20Koufo,%20Sithonia,%20Chalkidiki,%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sarti,%20church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Karidi%20beach,%20Sithonia,%20Chalkidiki,%20Greece.jpg"}'::text[], '{"Nikiti – stará čtvrť","Neos Marmaras","Parthenonas","Restaurace: O Platanos (Parthenonas)","Porto Koufo","Sarti","Vourvourou a pláž Karydi"}'::text[], '{"GR"}'::text[], false, 4070, 'approved');

  -- Kréta – Chania, Elafonisi a Falassarna
  delete from public.routes where name = 'Kréta – Chania, Elafonisi a Falassarna' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kréta – Chania, Elafonisi a Falassarna', 'Okruh nejzápadnějším cípem Kréty z benátské Chanie k růžovým plážím Elafonisi a zpět přes Falassarnu. Silnice se provléká skalní soutěskou Topolia, kde jednosměrný tunel proráží útes, a pak padá serpentinami k laguně, která patří k nejkrásnějším plážím Evropy. Návrat po západním pobřeží nabízí výhledy na otevřené Libyjské moře a zlatou pláž Falassarna, proslulou západy slunce. Krétské silnice jsou úzké, se štěrkem v zatáčkách a místními řidiči, kteří jezdí středem — držte si rezervu. Ideální je květen, červen nebo září; v červenci a srpnu vyjeďte na Elafonisi před devátou, jinak nezaparkujete. Večer v Chanii zakončete u benátského přístavu.', 'loop', 160, 270, 'medium',
     '[{"lat": 35.5138, "lng": 24.0180, "label": "Start: Chania"}, {"lat": 35.4210, "lng": 23.6810, "label": "Soutěska Topolia"}, {"lat": 35.2716, "lng": 23.5416, "label": "Elafonisi"}, {"lat": 35.4936, "lng": 23.5786, "label": "Falassarna"}, {"lat": 35.4940, "lng": 23.6550, "label": "Kissamos"}, {"lat": 35.5138, "lng": 24.0180, "label": "Cíl: Chania"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=35.5138,24.0180&destination=35.5138,24.0180&travelmode=driving&waypoints=35.4210,23.6810%7C35.2716,23.5416%7C35.4936,23.5786%7C35.4940,23.6550', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Old%20Venetian%20Harbour%20in%20Chania,%20Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20Old%20Venetian%20Harbour%20in%20Chania,%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Topolia%20Gorge%20-%20Crete,%20Greece%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Elafonisi%20Greece%20Crete%2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Creta,spiaggia%20di%20Falassarna%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Port%20of%20Kissamos%20in%20Crete,%20Greece%20001.jpg"}'::text[], '{"Chania – benátský přístav","Soutěska Topolia","Elafonisi","Falassarna","Kissamos","Restaurace: Tamam (Chania)"}'::text[], '{"GR"}'::text[], false, 4080, 'approved');

  -- Argolida – Nafplio, Mykény a Epidauros
  delete from public.routes where name = 'Argolida – Nafplio, Mykény a Epidauros' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Argolida – Nafplio, Mykény a Epidauros', 'Okruh kolébkou evropských dějin: za jediný den projedete mykénskou citadelu, antický Korint, slavný průplav i dokonalé divadlo v Epidauru a večer zaparkujete v nejromantičtějším městě Řecka. Silnice Argolidy vedou mezi pomerančovníkovými sady a vinicemi, mezi Epidaurem a Nafpliem si užijete svižné zatáčky v borovicových kopcích. Provoz je mimo hlavní tahy klidný a povrch dobrý — trasa vhodná i pro cestovní enduro s plnou bagáží. Nejpříjemněji je tu na jaře, kdy voní květy pomerančovníků, a na podzim; památky otevírají v osm, využijte toho. V Nafpliu vystoupejte 999 schodů na pevnost Palamidi — nejlépe až po odložení helmy a bot.', 'loop', 170, 250, 'easy',
     '[{"lat": 37.5680, "lng": 22.8090, "label": "Start: Nafplio"}, {"lat": 37.7308, "lng": 22.7566, "label": "Mykény"}, {"lat": 37.9059, "lng": 22.8797, "label": "Starověký Korint"}, {"lat": 37.9333, "lng": 22.9833, "label": "Korintský průplav"}, {"lat": 37.5961, "lng": 23.0791, "label": "Epidauros"}, {"lat": 37.5680, "lng": 22.8090, "label": "Cíl: Nafplio"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=37.5680,22.8090&destination=37.5680,22.8090&travelmode=driving&waypoints=37.7308,22.7566%7C37.9059,22.8797%7C37.9333,22.9833%7C37.5961,23.0791', 'https://commons.wikimedia.org/wiki/Special:FilePath/Palamidi%20fortress%20(Nafplio,%20Greece).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palamidi%20fortress%20(Nafplio,%20Greece).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lions-Gate-Mycenae.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Apollo%20Ancient%20Corinth.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corinth%20Canal%20(corinth-canal).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Theatre%20of%20Epidaurus%20OLC.jpg"}'::text[], '{"Nafplio – pevnost Palamidi","Mykény – Lví brána","Starověký Korint","Korintský průplav","Divadlo v Epidauru","Restaurace: Ta Fanaria (Nafplio)"}'::text[], '{"GR"}'::text[], false, 4090, 'approved');

  -- Attika – mys Sounion a chrám Poseidona
  delete from public.routes where name = 'Attika – mys Sounion a chrám Poseidona' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Attika – mys Sounion a chrám Poseidona', 'Klasická athénská vyjížďka po pobřežní silnici Athénské riviéry až na mys Sounion, kde nad útesy září mramorový chrám Poseidona. Pobřežka se vlní nad zátokami kolem jezera Vouliagmeni a nabízí svižné oblouky s mořem na dosah; zpět se vracíte vnitrozemím přes hornické Lavrio a Artemidinu svatyni ve Vravroně. Trasa je nenáročná a krásně sjízdná po celý rok — v zimě si jen ohlídejte vítr na mysu. O víkendech na pobřežce jezdí půlka Athén, vyjeďte proto brzy ráno, nebo naopak odpoledne s návratem po setmění. Západ slunce u Poseidonova chrámu patří k největším divadlům Řecka; přijeďte hodinu předem, ať stihnete parkování i vstup.', 'loop', 140, 210, 'easy',
     '[{"lat": 37.8620, "lng": 23.7540, "label": "Start: Athény – Glyfada"}, {"lat": 37.8064, "lng": 23.7862, "label": "Jezero Vouliagmeni"}, {"lat": 37.6503, "lng": 24.0203, "label": "Mys Sounion"}, {"lat": 37.7146, "lng": 24.0566, "label": "Lavrio"}, {"lat": 37.9262, "lng": 23.9945, "label": "Vravrona"}, {"lat": 37.8620, "lng": 23.7540, "label": "Cíl: Athény – Glyfada"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=37.8620,23.7540&destination=37.8620,23.7540&travelmode=driving&waypoints=37.8064,23.7862%7C37.6503,24.0203%7C37.7146,24.0566%7C37.9262,23.9945', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Sounion%20and%20temple%20of%20Poseidon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Limni%20Vouliagmenis%20kalokairi.JPEG","https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Sounion%20and%20temple%20of%20Poseidon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Capo%20Sounion%20panorama.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Agardite%20Lavrio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brauron%20-%20Votive%20Relief3.jpg"}'::text[], '{"Jezero Vouliagmeni","Chrám Poseidona na mysu Sounion","Restaurace: Syrtaki (Sounion)","Lavrio – město stříbrných dolů","Vravrona – svatyně Artemidy"}'::text[], '{"GR"}'::text[], false, 4100, 'approved');

end $$;
